(6774161, 1016351, 113156, '<td valign="top">Great morning treat for me, made me smile, hope my poochie gets over his fear of water.</td>', 'Great morning treat for me, made me smile, hope my poochie gets over his fear of water.', '2012-05-21 05:18:58.000000', NULL, 1),
