(6775388, 1016359, 99412, '<td valign="top">Beautiful photo.  9</td>', 'Beautiful photo.  9', '2012-05-22 15:15:32.000000', NULL, 1),
(6775502, 1016541, 142473, '<td valign="top">Great shot, though I would have loved a little more depth to the clouds.  A little burning to the clouds and the sand could have really made this pop in an AA sorta way.</td>', 'Great shot, though I would have loved a little more depth to the clouds.  A little burning to the clouds and the sand could have really made this pop in an AA sorta way.', '2012-05-22 17:21:41.000000', NULL, 1),
(6775505, 1016494, 142473, '<td valign="top">Great textures!  This is the kind of shot I would love to take.  Looks like AA''s processing, but maybe not his "normal" subject.  Cheers.</td>', 'Great textures!  This is the kind of shot I would love to take.  Looks like AA''s processing, but maybe not his "normal" subject.  Cheers.', '2012-05-22 17:22:50.000000', NULL, 1),
(6775554, 1016166, 104230, '<td valign="top">Beautiful capture of light here.</td>', 'Beautiful capture of light here.', '2012-05-22 18:02:31.000000', NULL, 1),
(6775669, 1016496, 142363, '<td valign="top">I am not voting because I have no frame of reference for the challenge, but i AM looking....and I freaking LOVE this.  the soft whispiness of the clouds - the stark contrast to the wood - I really just adore this.</td>', 'I am not voting because I have no frame of reference for the challenge, but i AM looking....and I freaking LOVE this.  the soft whispiness of the clouds - the stark contrast to the wood - I really just adore this.', '2012-05-22 20:24:09.000000', NULL, 1),
(6775670, 1015569, 142363, '<td valign="top">The longer I look at this, the more I see.  I confess that I am not voting (since I know nothing about Adams) - but I am commenting - because I am really enjoying the diversity of the entries.  This photo is especially compelling and intriguing and wonderful to me.</td>', 'The longer I look at this, the more I see.  I confess that I am not voting (since I know nothing about Adams) - but I am commenting - because I am really enjoying the diversity of the entries.  This photo is especially compelling and intriguing and wonderful to me.', '2012-05-22 20:26:09.000000', NULL, 1),
(6775853, 1016494, 54446, '<td valign="top">Very good representation of AA''s style for this type of immage.  I also love the composition.  The tonal range is magnificent with rich dark tones and nicely contrasted brighter areas.  Bumping this to a "9".</td>', 'Very good representation of AA''s style for this type of immage.  I also love the composition.  The tonal range is magnificent with rich dark tones and nicely contrasted brighter areas.  Bumping this to a "9".', '2012-05-22 22:48:24.000000', NULL, 1),
(6776145, 1016154, 135629, '<td valign="top">Love this shot, the B&amp;W processing is great, at first I was wondering about different DOF but in the spirit of Ansel I think you are on the right track here. I gave it very high marks, good luck in the challenge.</td>', 'Love this shot, the B&W processing is great, at first I was wondering about different DOF but in the spirit of Ansel I think you are on the right track here. I gave it very high marks, good luck in the challenge.', '2012-05-23 02:52:17.000000', NULL, 1),
(6776147, 1016419, 135629, '<td valign="top">I have been going back through the images to comment, to me this one stands alone as both a very good image, and also capturing a classic feel of a possible Adams shot, good luck in the challenge I''d put this on the front page.</td>', 'I have been going back through the images to comment, to me this one stands alone as both a very good image, and also capturing a classic feel of a possible Adams shot, good luck in the challenge I''d put this on the front page.', '2012-05-23 02:53:56.000000', NULL, 1),
(6776148, 1015546, 135629, '<td valign="top">Pristine. This is a great image, it made me stop and check out the details. Good luck in the challenge.</td>', 'Pristine. This is a great image, it made me stop and check out the details. Good luck in the challenge.', '2012-05-23 02:56:05.000000', NULL, 1),
(6776150, 1016369, 135629, '<td valign="top">Great image, love the details seen through the water and sharpness all the way to the tree line. Good luck in the challenge.</td>', 'Great image, love the details seen through the water and sharpness all the way to the tree line. Good luck in the challenge.', '2012-05-23 02:57:09.000000', NULL, 1),
