(6776466, 1016446, 114225, '<td valign="top">I gave this a 5. I was wavering giving it a 6, because the scene is beautiful. But the clouds are bugging me, they nook unnatural.</td>', 'I gave this a 5. I was wavering giving it a 6, because the scene is beautiful. But the clouds are bugging me, they nook unnatural.', '2012-05-23 10:42:56.000000', NULL, 1),
(6776469, 1016309, 114225, '<td valign="top">Very cool root system. Too bad for the buildings in the background, they steal a lot of attention.</td>', 'Very cool root system. Too bad for the buildings in the background, they steal a lot of attention.', '2012-05-23 10:43:24.000000', NULL, 1),
(6776473, 1016246, 114225, '<td valign="top">I''m liking the rich blacks here quite a bit.</td>', 'I''m liking the rich blacks here quite a bit.', '2012-05-23 10:44:45.000000', NULL, 1),
(6776474, 1016566, 114225, '<td valign="top">Very Ansel like scene with the river in the foreground.</td>', 'Very Ansel like scene with the river in the foreground.', '2012-05-23 10:45:10.000000', NULL, 1),
(6776475, 1016359, 114225, '<td valign="top">Great job finding beauty where others may not look.</td>', 'Great job finding beauty where others may not look.', '2012-05-23 10:45:38.000000', NULL, 1),
(6776477, 1016125, 114225, '<td valign="top">Wow, the patterns of the rocks seem to be continued into the clouds of the sky. Very cool.</td>', 'Wow, the patterns of the rocks seem to be continued into the clouds of the sky. Very cool.', '2012-05-23 10:46:23.000000', NULL, 1),
(6776479, 1016326, 114225, '<td valign="top">Very nice use of vectors in this photo.</td>', 'Very nice use of vectors in this photo.', '2012-05-23 10:47:13.000000', NULL, 1),
(6776482, 1016564, 114225, '<td valign="top">Great setting and good job using the light you had.<br/> <br/>The clouds are a double edged sword in this. On one had, they add interest to the sky. On the other hand they prevent any shadow that could be cast by the tree, which would be cool.</td>', 'Great setting and good job using the light you had. The clouds are a double edged sword in this. On one had, they add interest to the sky. On the other hand they prevent any shadow that could be cast by the tree, which would be cool.', '2012-05-23 10:48:26.000000', NULL, 1),
(6776488, 1016494, 114225, '<td valign="top">I really like this. The high contrast and stark lines really do look like an Ansel Adams style shot.</td>', 'I really like this. The high contrast and stark lines really do look like an Ansel Adams style shot.', '2012-05-23 10:49:22.000000', NULL, 1),
(6776498, 1016279, 114225, '<td valign="top">Very nice use of natural framing on each side of this image.</td>', 'Very nice use of natural framing on each side of this image.', '2012-05-23 10:53:58.000000', NULL, 1),
(6776500, 1015546, 114225, '<td valign="top">Perfect light for this shot to really show off the curves and details.</td>', 'Perfect light for this shot to really show off the curves and details.', '2012-05-23 10:54:53.000000', NULL, 1),
(6776501, 1016497, 114225, '<td valign="top">Excellent view and photograph. To be more Ansel like, I think there needs to be some deeper blacks, but I like this.</td>', 'Excellent view and photograph. To be more Ansel like, I think there needs to be some deeper blacks, but I like this.', '2012-05-23 10:55:24.000000', NULL, 1),
(6776611, 1016359, 27812, '<td valign="top">Masterpiece Robt. You are one of few who has mastered the zones.</td>', 'Masterpiece Robt. You are one of few who has mastered the zones.', '2012-05-23 12:58:42.000000', NULL, 1),
(6776615, 1015546, 27812, '<td valign="top">Taking the zone system into account here, I miss true black, something you could have had. Sorry, 8.</td>', 'Taking the zone system into account here, I miss true black, something you could have had. Sorry, 8.', '2012-05-23 13:00:48.000000', NULL, 1),
(6776692, 1016279, 147586, '<td valign="top">There''s nothing in this photograph that I dislike.  I''d hang it on my wall :)</td>', 'There''s nothing in this photograph that I dislike.  I''d hang it on my wall :)', '2012-05-23 14:23:02.000000', NULL, 1),
(6777096, 1016263, 114285, '<td valign="top">A real contender I feel for a ribbon.</td>', 'A real contender I feel for a ribbon.', '2012-05-24 05:01:11.000000', NULL, 1),
(6777097, 1016347, 114285, '<td valign="top">Nice scene, but the sky is a bit blown out, but then again maybe you couldn''t of avoided it.</td>', 'Nice scene, but the sky is a bit blown out, but then again maybe you couldn''t of avoided it.', '2012-05-24 05:02:07.000000', NULL, 1),
(6777492, 1016279, 144791, '<td valign="top">What color is your ribbon? Nice work...</td>', 'What color is your ribbon? Nice work...', '2012-05-24 16:44:08.000000', NULL, 1),
(6777665, 1016561, 60495, '<td valign="top">Love it, looks like you took it from your helicopter!</td>', 'Love it, looks like you took it from your helicopter!', '2012-05-24 21:26:00.000000', NULL, 1),
(6778036, 1016361, 110937, '<td valign="top">Simply Amazing...what great beauty god has given us !</td>', 'Simply Amazing...what great beauty god has given us !', '2012-05-25 05:18:37.000000', NULL, 1),
(6778041, 1015569, 113591, '<td valign="top">Title scored you two extra points</td>', 'Title scored you two extra points', '2012-05-25 05:34:08.000000', NULL, 1),
