(6779047, 1016465, 104230, '<td valign="top">Nice tones but marred somewhat by over-sharpening, flat light on the mountain range and a little too much detail for a typical Adams type image in my opinion. I like the shape of the mountain range and its peak and this is nice subject for a black and white image.</td>', 'Nice tones but marred somewhat by over-sharpening, flat light on the mountain range and a little too much detail for a typical Adams type image in my opinion. I like the shape of the mountain range and its peak and this is nice subject for a black and white image.', '2012-05-26 16:39:05.000000', NULL, 1),
(6779055, 1016222, 104230, '<td valign="top">An interesting subject but the processing has resulted in mid tones without the extremes of light and dark, and thus lacks the Ansel Adams touch.</td>', 'An interesting subject but the processing has resulted in mid tones without the extremes of light and dark, and thus lacks the Ansel Adams touch.', '2012-05-26 17:11:06.000000', NULL, 1),
(6779119, 1016369, 136989, '<td valign="top">I like what I can see but the fog creates too much white/dead space for my preference.</td>', 'I like what I can see but the fog creates too much white/dead space for my preference.', '2012-05-26 21:09:00.000000', NULL, 1),
