INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6779922, 1015546, 96751, '<td valign="top">Hypnotic. Congrats on the monster score and the blue.</td>', 'Hypnotic. Congrats on the monster score and the blue.', '2012-05-28 11:37:32.000000', NULL, 0),
(6779924, 1016385, 44877, '<td valign="top">Beautiful, Sarah! Congratulations on the great placement. Sorry it took a hit from where you told me it was earlier. But still very nice - and a good shot to have in your portfolio.</td>', 'Beautiful, Sarah! Congratulations on the great placement. Sorry it took a hit from where you told me it was earlier. But still very nice - and a good shot to have in your portfolio.', '2012-05-28 11:43:35.000000', NULL, 0),
(6779926, 1016430, 76335, '<td valign="top">Very exciting.</td>', 'Very exciting.', '2012-05-28 11:51:34.000000', NULL, 0),
(6779928, 1015546, 112739, '<td valign="top">I also thought this would be the winner What a great shot and a great score. Congrats! Must feel strange to get an 8 vote and have your score drop!</td>', 'I also thought this would be the winner What a great shot and a great score. Congrats! Must feel strange to get an 8 vote and have your score drop!', '2012-05-28 11:55:07.000000', NULL, 0),
(6779930, 1016279, 112739, '<td valign="top">Wow Richard, you are tearing it up around here!  Congrats on the red with another text book image.  And thank you for your kind comments.</td>', 'Wow Richard, you are tearing it up around here!  Congrats on the red with another text book image.  And thank you for your kind comments.', '2012-05-28 11:59:32.000000', NULL, 0),
(6779934, 1016361, 112739, '<td valign="top">Congrats on HM Oz!</td>', 'Congrats on HM Oz!', '2012-05-28 12:06:28.000000', NULL, 0),
(6779936, 1015949, 112739, '<td valign="top">What a beautiful setting. And expertly captured and processed. Congrats!</td>', 'What a beautiful setting. And expertly captured and processed. Congrats!', '2012-05-28 12:08:03.000000', NULL, 0),
(6779937, 1016359, 112739, '<td valign="top">Yes, the grass processing is so delicate, by the hand of a master. Love it!</td>', 'Yes, the grass processing is so delicate, by the hand of a master. Love it!', '2012-05-28 12:09:38.000000', NULL, 0),
(6779940, 1016351, 16148, '<td valign="top">Double bling!  Appreciation, for the clever shot, is well deserved.</td>', 'Double bling!  Appreciation, for the clever shot, is well deserved.', '2012-05-28 12:12:53.000000', NULL, 0),
(6779944, 1016385, 112739, '<td valign="top">I am in love with your clouds! So much depth and character. Congrats on TT!</td>', 'I am in love with your clouds! So much depth and character. Congrats on TT!', '2012-05-28 12:16:56.000000', NULL, 0),
(6779945, 1016567, 112739, '<td valign="top">Congrats on TT Mark. Great result with your limited time.</td>', 'Congrats on TT Mark. Great result with your limited time.', '2012-05-28 12:18:01.000000', NULL, 0),
(6779958, 1015546, 104230, '<td valign="top">Just wonderful. I love sand and shadow images and Cape Cod can be a pretty cool place to take them at certain times of year, but the sheer scale of this and the sweeping wind swept lines is in another class altogether.  Congrats on the wonderful score and the well deserved blue ribbon.</td>', 'Just wonderful. I love sand and shadow images and Cape Cod can be a pretty cool place to take them at certain times of year, but the sheer scale of this and the sweeping wind swept lines is in another class altogether.  Congrats on the wonderful score and the well deserved blue ribbon.', '2012-05-28 12:34:47.000000', NULL, 0),
(6780017, 1016361, 73942, '<td valign="top">Congrats Oliver!</td>', 'Congrats Oliver!', '2012-05-28 13:30:22.000000', NULL, 0),
(6780019, 1016541, 73942, '<td valign="top">wonderful finish, congrats on a top 20!</td>', 'wonderful finish, congrats on a top 20!', '2012-05-28 13:31:57.000000', NULL, 0),
(6780034, 1016419, 104230, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by blindjustice:</b></div><hr/><i> The processing is subtle and fine. I especially like the door and the window, the lines giving movement to the boat. </i></td></tr></table> <br/> <br/>Thanks Paul. Those were definitively key elements that drew me to this, plus the light on the oars. <br/> <br/>Regarding the crop. Thanks for the feedback from those who commented on it.  I was at the wide end of this lens and I couldn''t stand any further back. I was up against a locked door.  I could have switched to the 10-22mm lens but I really wanted the benefit of the L glass in my 24-105mm lens plus the area around the bottom of the boat was marred (IMO) by metal supports and other objects.  Once home, I considered cropping more off the bottom to get away from the look of having "just" missed getting all the boat in the image, but to my eyes that just wasn''t as interesting. <br/><br/><i>Message edited by author 2012-05-31 21:03:41.</i></td>', 'Originally posted by blindjustice: The processing is subtle and fine. I especially like the door and the window, the lines giving movement to the boat.   Thanks Paul. Those were definitively key elements that drew me to this, plus the light on the oars.  Regarding the crop. Thanks for the feedback from those who commented on it.  I was at the wide end of this lens and I couldn''t stand any further back. I was up against a locked door.  I could have switched to the 10-22mm lens but I really wanted the benefit of the L glass in my 24-105mm lens plus the area around the bottom of the boat was marred (IMO) by metal supports and other objects.  Once home, I considered cropping more off the bottom to get away from the look of having "just" missed getting all the boat in the image, but to my eyes that just wasn''t as interesting. ', '2012-05-28 13:46:48.000000', '2012-05-31 22:03:41.000000', 0),
(6780052, 1016494, 112972, '<td valign="top">This is just like a beautiful painting!  Well done, Anita!</td>', 'This is just like a beautiful painting!  Well done, Anita!', '2012-05-28 14:26:18.000000', NULL, 0),
(6780054, 1015546, 112972, '<td valign="top">A breathtaking image!</td>', 'A breathtaking image!', '2012-05-28 14:29:21.000000', NULL, 0),
